Roll Random Beastmen NPC.command:
// Macro to create a random NPC, being sent in a whisper to GMs on the server.

const namesTableID = game.tables.find(o => o.name === "Zaginiona Cytadela: Imiona Ludzi-bestii")._id;
const namesTable = await game.tables.get(namesTableID);
const namesResult = await namesTable.draw({displayChat: false});
const names = await namesResult.results.pop().getHTML();

const appearanceTableID = game.tables.find(o => o.name === "Zaginiona Cytadela: Wygląd Ludzi-bestii")._id;
const appearanceTable = await game.tables.get(appearanceTableID);
const appearanceResult = await appearanceTable.draw({displayChat: false});
const appearance = await appearanceResult.results.pop().getHTML();

const behaviorTableID = game.tables.find(o => o.name === "Zaginiona Cytadela: Zachowania Ludzi-bestii")._id;
const behaviorTable = await game.tables.get(behaviorTableID);
const behaviorResult = await behaviorTable.draw({displayChat: false});
const behavior = await behaviorResult.results.pop().getHTML();

const message = `<p> @UUID[Compendium.shadowdark.monsters.Actor.k8tAgECWIzPIStGU]{Człowiek-bestia} o wyglądzie <b>${appearance}</b>, nazywający się <b>${names}</b> 
jest <b>${behavior}</b>.</p>`;

const chatData = {
user: game.user._id,
speaker: ChatMessage.getSpeaker(),
content: message,
whisper: game.users.filter(u => u.isGM).map(u => u._id),
};

ChatMessage.create(chatData, {});

